/*
 * A376566  Lexicographically earliest sequence of positive integers such that
 *          for any n > 0, there is an even number of k's such that 1 <= k < n
 *          and a(n) divides a(k).
 * https://oeis.org/A376566
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   the lexicographically earliest sequence of positive integers
 *            such that for each n > 0 the number of k with 1 ≤ k < n and a(n)
 *            | a(k) is even. The sequence satisfies: a(2*k-1) = 1 (for all k
 *            > 0) and it is generated by iteratively choosing, at each even
 *            position, the smallest integer whose current...
 * Range:     u8 n <= 85, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
#include "../utils/floor_sqrt.h"

static seq_t *seq   = NULL;   /* Terms of the sequence (1‑based indexing in logic) */
static size_t seq_cap = 0;    /* Allocated capacity for seq  */
static size_t seq_len = 0;    /* Number of terms already generated */

static seq_t *c     = NULL;   /* Counts of earlier multiples for each divisor */
static size_t c_cap = 0;      /* Allocated capacity for c  */

/* Ensure that the divisor count array covers at least index 'idx' */
static void ensure_c_index(size_t idx)
{
    if (idx < c_cap) return;
    size_t new_cap = c_cap == 0 ? 16 : c_cap * 2;
    while (new_cap <= idx) new_cap *= 2;
    seq_t *tmp = (seq_t *)realloc(c, new_cap * sizeof(seq_t));
    if (!tmp) exit(EXIT_FAILURE);
    for (size_t i = c_cap; i < new_cap; ++i) tmp[i] = 0;
    c = tmp;
    c_cap = new_cap;
}

/* Ensure that the sequence array can hold at least 'needed' terms */
static void ensure_seq_capacity(size_t needed)
{
    if (needed <= seq_cap) return;
    size_t new_cap = seq_cap == 0 ? 16 : seq_cap * 2;
    while (new_cap < needed) new_cap *= 2;
    seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
    if (!tmp) exit(EXIT_FAILURE);
    seq = tmp;
    seq_cap = new_cap;
}

/* Generate terms up to index 'n' (1‑based) if not already done */
static void extend_upto(idx_t n)
{
    size_t target = (size_t)n;
    if (target <= seq_len) return;      /* already generated */

    ensure_seq_capacity(target);
    if (c_cap == 0) {
        c_cap = 16;
        c = (seq_t *)realloc(c, c_cap * sizeof(seq_t));
        if (!c) exit(EXIT_FAILURE);
        for (size_t i = 0; i < c_cap; ++i) c[i] = 0;
    }

    for (size_t i = seq_len + 1; i <= target; ++i) {
        seq_t val;

        /* odd indices must be 1 */
        if ((i & 1) == 1) {
            val = 1;
        } else {   /* even index: choose smallest v ≥ 2 with even count */
            size_t candidate = 2;
            while (1) {
                if (candidate >= c_cap) ensure_c_index(candidate);
                if ((c[candidate] & 1) == 0) break;
                ++candidate;
            }
            val = (seq_t)candidate;
        }

        /* store the value */
        seq[i - 1] = val;

        /* update divisor counts for all divisors of 'val' */
        seq_t v = val;
        seq_t sqrt_v = floor_sqrt(v);
        for (size_t d = 1; d <= (size_t)sqrt_v; ++d) {
            seq_t dd = (seq_t)d;
            if (v % dd == 0) {
                size_t d1 = d;
                ensure_c_index(d1);
                c[d1]++;

                size_t d2 = (size_t)(v / dd);
                if (d2 != d1) {
                    ensure_c_index(d2);
                    c[d2]++;
                }
            }
        }

        ++seq_len;
    }
}

/* Public function required by the interface */
seq_t a(idx_t n)
{
    if (n == 0) return 0;           /* undefined, but safe */
    extend_upto(n);
    return seq[(size_t)n - 1];
}
